// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We fuzz a maintenance value (as uint256 raw representing the UFixed18 value divided by 1e18)
    // and an arbitrary caller address. We'll initialize the product with that maintenance and then
    // call maintenance(account) and compare to UFixed18Lib.ONE (which is 1e18 in wrapped form).
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 maintenanceWhole, address account) public {
        // Keep maintenanceWhole in reasonable bounds to avoid overflow when scaled by 1e18
        maintenanceWhole = bound(maintenanceWhole, 0, type(uint128).max);

        // Build a minimal ProductInfo with the fuzzed maintenance and reasonable defaults for other params.
        // We cannot construct all complex types exactly as in the original, but we only need to call initialize
        // on C which expects ProductInfo. We'll fabricate plausible values; the specific values besides maintenance
        // are irrelevant for this property.

        // Prepare payoffDefinition and oracle placeholders by deploying minimal stub contracts that satisfy interfaces.
        OracleStub oracle = new OracleStub();
        PayoffDefStub payoffDef = new PayoffDefStub();

        C.ProductInfo memory info;
        info.name = "p";
        info.symbol = "s";
        info.payoffDefinition = payoffDef.toPayoffDefinition();
        info.oracle = oracle;

        // Convert maintenanceWhole to UFixed18 by multiplying by 1e18 using the same scaling as library.
        // UFixed18.ONE is 1e18, so maintenanceWhole==1 should match ONE.
        uint256 scaled = maintenanceWhole * 1e18;
        // pack into the UFixed18 type via raw cast through storage: we cannot directly construct the typedef in test,
        // but C.initialize expects ProductInfo where maintenance is of type UFixed18. To work around, we construct
        // a local memory struct via assembly to set the maintenance field to the wrapped uint256 value.

        // Create a temporary bytes array equal to the memory layout of ProductInfo and then decode; simpler: call
        // initialize via low-level call encoding the arguments so we can pass the uint256 raw value for maintenance.

        // Build default values for other UFixed18 params
        uint256 fundingFee = 0;
        uint256 makerFee = 0;
        uint256 takerFee = 0;
        uint256 positionFee = 0;
        uint256 makerLimit = 1e18; // ONE

        // Build a minimal JumpRateUtilizationCurve with zeroed fields
        C.JumpRateUtilizationCurve memory curve = C.JumpRateUtilizationCurve({
            minRate: int128(0),
            maxRate: int128(0),
            targetRate: int128(0),
            targetUtilization: uint128(0)
        });

        // Prepare ABI-encoded ProductInfo to call initialize
        bytes memory encoded = abi.encode(
            // ProductInfo fields in order
            info.name,
            info.symbol,
            payoffDef.toPayoffDefinition(),
            address(oracle),
            scaled, // maintenance (UFixed18)
            fundingFee, // fundingFee (UFixed18)
            makerFee, // makerFee
            takerFee, // takerFee
            positionFee, // positionFee
            makerLimit, // makerLimit
            curve
        );

        // Call initialize via low-level call since types involve user-defined value types not available here directly.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.initialize.selector, abi.decode(encoded, (C.ProductInfo))));
        require(ok, "initialize failed");

        // Now query maintenance(account). The universal rule: maintenance(account) equals the stored maintenance parameter.
        // The mutant returns ONE always; so if we chose a maintenanceWhole != 1, the returned value should differ.

        // Call maintenance. It is external view and returns UFixed18 — the ABI will return a bytes-encoded uint256.
        (bool succ, bytes memory ret) = address(c).call(abi.encodeWithSelector(c.maintenance.selector, account));
        require(succ, "maintenance call reverted");

        uint256 returned = abi.decode(ret, (uint256));

        // ONE scaled value
        uint256 ONE = 1e18;

        // Single assertion: for the reference contract, returned must equal the stored scaled maintenance value we initialized with.
        // We assert that returned == scaled. This holds for the reference C for all inputs; the mutant that returns ONE will fail
        // whenever maintenanceWhole != 1.
        assertTrue(returned == scaled);
    }
}

// Minimal stubs to satisfy interfaces and types. They are intentionally small and deterministic.
contract OracleStub is C.IOracleProvider {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) { revert(); }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) { revert(); }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) { revert(); }
}

contract PayoffDefStub {
    function toPayoffDefinition() external pure returns (C.PayoffDefinition memory) {
        C.PayoffDefinition memory p;
        p.payoffType = C.PayoffDefinitionLib.PayoffType(0);
        p.payoffDirection = C.PayoffDefinitionLib.PayoffDirection(0);
        p.data = bytes30(0);
        return p;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the stored maintenance parameter (as a raw uint256 representing UFixed18)
    function testFuzz_property(uint256 rawMaintenance) public {
        // keep the maintenance parameter within a wide but reasonable range (as UFixed18 uses 1e18 base)
        uint256 maintenanceVal = bound(rawMaintenance, 0, type(uint256).max);

        // Build a minimal ProductInfo with the fuzzed maintenance encoded as UFixed18
        // We need to craft UFixed18 value: the library uses scaling by 1e18 in wrappers; the contract expects UFixed18 calldata
        // We cannot construct the UFixed18 type directly here, but C.initialize expects C.ProductInfo calldata from the contract's perspective.
        // However typically ProductInfo expects UFixed18 typed fields; since we cannot construct those directly in Solidity test easily,
        // we instead craft a bytes-packed memory struct via abi.encode and perform a low-level call to initialize.

        // Prepare other fields with innocuous values (zeros or empty) and use the fuzzed maintenance as the raw uint256 for maintenance.
        bytes memory name = abi.encodePacked("n");
        bytes memory symbol = abi.encodePacked("s");

        // Compose ProductInfo in ABI encoding order matching C.ProductInfo in the contract under test.
        // The struct fields order: name,string; symbol,string; payoffDefinition (struct: PayoffType,uint8,bytes30) -> awkward to build.
        // Simpler approach: call initialize under the assumption that controller is msg.sender expected by __UControllerProvider__initialize.
        // The contract's initialize does: __UControllerProvider__initialize(IController(msg.sender)); so msg.sender must be an IController contract address.
        // We'll deploy a minimal stub controller that implements the few functions used by initialization and later calls in this test.

        ControllerStub controller = new ControllerStub();
        // prepare a minimal ProductInfo with fields; we must match types exactly. We'll create the ProductInfo in Solidity by building the struct via memory.
        C.ProductInfo memory info;
        info.name = "n";
        info.symbol = "s";
        // payoffDefinition: create a dummy PayoffDefinition with valid() returning true via its methods; easiest is zero-initialized but ensure valid() passes in C (it calls payoffDefinition_.valid()).
        // The payoffDefinition.valid() is part of PayoffDefinitionLib in original; we cannot rely on it, but the reference contract used payoffDefinition_.valid() — assume zero struct is valid for test purposes.
        // To be safe, set payoffDefinition.data to non-zero bytes30.
        info.payoffDefinition.payoffType = C.PayoffDefinitionLib_PayoffType(uint8(0));
        info.payoffDefinition.payoffDirection = C.PayoffDefinitionLib_PayoffDirection(uint8(0));
        info.payoffDefinition.data = bytes30(0);

        // oracle: pass address(0) — __UPayoffProvider__initialize calls _updateOracle(address(oracle_), 0) which checks Address.isContract(newOracle) and will revert if not contract.
        // So we must deploy a stub oracle implementing IOracleProvider with required functions.
        OracleStub oracle = new OracleStub();
        info.oracle = IOracleProvider(address(oracle));

        // maintenance: set as UFixed18 value by wrapping raw uint scaled to 1e18; but UFixed18 is a type alias in the contract; we can set using UFixed18Lib.ONE etc not accessible here.
        // The simplest approach: call initialize via vm.prank from controller address so msg.sender is controller, and pass a ProductInfo with maintenance set using the contract's UFixed18 wrapper via encode.
        // However constructing UFixed18 typed value in test is permitted by using the concrete underlying type (uint256) and assigning to the struct field as the contract's type.

        // Use assembly to set the maintenance field in the memory struct to the raw uint scaled by 1e18 (to emulate UFixed18.wrap)
        uint256 scaledMaintenance = maintenanceVal; // let fuzz input be the raw wrapped value already (admissible domain)
        info.maintenance = C.UFixed18(scaledMaintenance);
        info.fundingFee = C.UFixed18(0);
        info.makerFee = C.UFixed18(0);
        info.takerFee = C.UFixed18(0);
        info.positionFee = C.UFixed18(0);
        info.makerLimit = C.UFixed18(type(uint256).max);
        // utilizationCurve: pass zero-initialized JumpRateUtilizationCurve
        C.JumpRateUtilizationCurve memory curve;
        curve.minRate = C.PackedFixed18.wrap(int128(0));
        curve.maxRate = C.PackedFixed18.wrap(int128(0));
        curve.targetRate = C.PackedFixed18.wrap(int128(0));
        curve.targetUtilization = C.PackedUFixed18.wrap(uint128(0));
        info.utilizationCurve = curve;

        // Call initialize with controller as msg.sender (per contract expectation)
        vm.prank(address(controller));
        c.initialize(info);

        // Now read maintenance via public getter for some arbitrary account address fuzzed by maintenanceVal (we must abide by test function parameter rule — we already have one param rawMaintenance)
        // Use an arbitrary account address derived from maintenanceVal to keep test non-constant
        address account = address(uint160(uint256(keccak256(abi.encodePacked(maintenanceVal)))));

        // Call maintenance(account) on c and assert it equals the stored maintenance value (as read by calling the contract's maintenance() function which should return the stored value in reference)
        C.UFixed18 memory stored = c.maintenance();
        C.UFixed18 memory viaCall = c.maintenance(account);

        // Single assertion: the reference contract returns the same value from maintenance() (product-level getter) and maintenance(account) (per-account view) for all inputs — the mutant returns ONE for maintenance(account) always, breaking when stored != ONE.
        // We assert that maintenance(account) equals maintenance() (the stored product maintenance). This holds for reference for all inputs; mutant will fail when stored != ONE.
        assertTrue(keccak256(abi.encodePacked(viaCall)) == keccak256(abi.encodePacked(stored)));
    }
}

// Minimal stubs used to satisfy contract dependencies
interface IOracleProvider {
    function sync() external returns (IOracleProvider.OracleVersion memory);
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (IOracleProvider.OracleVersion memory);
    struct OracleVersion { uint256 version; uint256 timestamp; C.Fixed18 price; }
}

contract OracleStub is IOracleProvider {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        IOracleProvider.OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = C.Fixed18.wrap(0);
        return v;
    }
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) { return sync(); }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) { return sync(); }
}

contract ControllerStub {
    function owner() external view returns (address) { return address(this); }
    function isProduct(C) external pure returns (bool) { return true; }
    function coordinatorFor(C) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return address(this); }
    function paused() external pure returns (bool) { return false; }
    function collaterall() external pure {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct DummyOracle {}

    function setUp() public { c = new C(); }

    // fuzz the stored maintenance parameter; choose any address as account to query
    function testFuzz_property(uint256 maintenanceRaw, address account) public {
        // keep maintenance within a wide valid UFixed18 range (scaled by 1e18 in library)
        maintenanceRaw = bound(maintenanceRaw, 0, type(uint256).max / 1e18);

        // Construct ProductInfo in calldata-style via memory struct packing
        // We need to craft a C.ProductInfo; since C is imported, we can use the type via C.ProductInfo
        C.ProductInfo memory info;
        info.name = "p";
        info.symbol = "s";

        // Minimal valid payoffDefinition and oracle addresses: use address(this) as placeholder
        // The contract's __UPayoffProvider__initialize will call Address.isContract on oracle; address(this) is a contract
        // Put dummy payoffDefinition and oracle to satisfy initialize; use zeroed structs for others
        // We cannot construct nested library types easily; however ProductInfo expects types defined in scope — use defaults

        // For types like PayoffDefinition and IOracleProvider, we craft minimal values via abi.encode then decode
        // But simpler: create local variables matching the fields and assign via assembly to the memory struct

        // Prepare fields individually
        // productInfo fields: PayoffDefinition payoffDefinition; IOracleProvider oracle; UFixed18 maintenance; UFixed18 fundingFee; UFixed18 makerFee; UFixed18 takerFee; UFixed18 positionFee; UFixed18 makerLimit; JumpRateUtilizationCurve utilizationCurve;
        // We will set oracle to address(this) and zero everything else except maintenance

        // Build UFixed18 by multiplying maintenanceRaw by 1e18 to match library semantics
        uint256 BASE = 1e18;
        uint256 maintenanceScaled = maintenanceRaw * BASE;

        // Use low-level assembly to set complex struct fields inside info
        bytes32 ptr;
        assembly { ptr := info }
        // Layout is implementation specific; easier approach: call initialize via try/catch with encoded calldata

        // Build calldata for initialize(ProductInfo)
        // We will ABI-encode a ProductInfo tuple matching the declaration in C
        // For payoffDefinition use zeros bytes30 and enums default 0
        bytes memory payoffDef = abi.encode(uint8(0), uint8(0), bytes30(0));
        address oracleAddr = address(this);
        uint256 maintenanceEncoded = maintenanceScaled;
        uint256 fundingFee = 0;
        uint256 makerFee = 0;
        uint256 takerFee = 0;
        uint256 positionFee = 0;
        uint256 makerLimit = 0;
        // JumpRateUtilizationCurve: four packed fields; just zeros
        bytes memory utilizationCurve = abi.encodePacked(bytes32(0), bytes32(0), bytes32(0), bytes32(0));

        bytes memory productInfoEncoded = abi.encode(
            // name, symbol
            string("p"), string("s"),
            // payoffDefinition (as tuple: uint8,uint8,bytes30)
            uint8(0), uint8(0), bytes30(0),
            // oracle
            oracleAddr,
            // maintenance .. makerLimit
            maintenanceEncoded,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            // utilizationCurve - we need to encode struct with 4 fields: PackedFixed18 minRate; PackedFixed18 maxRate; PackedFixed18 targetRate; PackedUFixed18 targetUtilization;
            // use zeros
            bytes32(0), bytes32(0), bytes32(0), bytes32(0)
        );

        bytes memory initCalldata = abi.encodeWithSignature("initialize((string,string,uint8,uint8,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,bytes32,bytes32,bytes32,bytes32))", productInfoEncoded);

        // The above encoding is complex; instead call c.initialize by constructing a simple compatible struct in memory via a helper contract
        // Deploy a small helper that calls initialize with structured args
        InitializerHelper helper = new InitializerHelper();
        // Call helper to initialize c with our parameters
        helper.callInitialize(address(c), maintenanceScaled);

        // Now call maintenance(account) and assert it equals the stored maintenance (i.e., maintenanceScaled interpreted as UFixed18)
        // The reference returns the stored maintenance; the mutant would always return ONE (BASE)
        // We check inequality with ONE only when maintenanceScaled != BASE so that mutant would differ

        // Read returned maintenance
        bool ok;
        try c.maintenance(account) returns (uint256 m) {
            // Since UFixed18 is a type alias, the ABI returns uint256
            // Compare m to maintenanceScaled
            ok = (m == maintenanceScaled);
        } catch {
            ok = false;
        }

        // The general rule: for every maintenanceScaled input, reference returns stored maintenanceScaled. So ok must be true for all inputs.
        // Mutant returns BASE for all inputs; for inputs where maintenanceScaled != BASE the mutant will make ok false; fuzzer can find such inputs.
        assertTrue(ok);
    }
}

contract InitializerHelper {
    // Minimal structs to call C.initialize
    struct PayoffDefinition {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }
    struct JumpRateUtilizationCurve {
        bytes32 minRate;
        bytes32 maxRate;
        bytes32 targetRate;
        bytes32 targetUtilization;
    }
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }

    function callInitialize(address cAddr, uint256 maintenanceScaled) external {
        C target = C(cAddr);
        PayoffDefinition memory pd = PayoffDefinition({payoffType: 0, payoffDirection: 0, data: bytes30(0)});
        JumpRateUtilizationCurve memory jc = JumpRateUtilizationCurve({minRate: bytes32(0), maxRate: bytes32(0), targetRate: bytes32(0), targetUtilization: bytes32(0)});
        ProductInfo memory info = ProductInfo({
            name: "p",
            symbol: "s",
            payoffDefinition: pd,
            oracle: address(this),
            maintenance: maintenanceScaled,
            fundingFee: 0,
            makerFee: 0,
            takerFee: 0,
            positionFee: 0,
            makerLimit: 0,
            utilizationCurve: jc
        });
        // Need to cast and call initialize; use low-level call with ABI-encoded tuple matching C.ProductInfo
        bytes memory data = abi.encodeWithSelector(bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(bytes32,bytes32,bytes32,bytes32)))")),
            info.name,
            info.symbol,
            info.payoffDefinition.payoffType,
            info.payoffDefinition.payoffDirection,
            info.payoffDefinition.data,
            info.oracle,
            info.maintenance,
            info.fundingFee,
            info.makerFee,
            info.takerFee,
            info.positionFee,
            info.makerLimit,
            info.utilizationCurve.minRate,
            info.utilizationCurve.maxRate,
            info.utilizationCurve.targetRate,
            info.utilizationCurve.targetUtilization
        );
        (bool s,) = cAddr.call(data);
        require(s, "init failed");
    }
}

