pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct ProductInfoHelper {
        string name;
        string symbol;
        IOracleProvider oracle;
        PayoffDefinition payoffDefinition;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }

    // We import the necessary types locally to construct ProductInfo without redeclaring C.
    // Minimal forward declarations to allow compilation of test file only; actual types come from C.
    // These declarations match names used in C's interface and only serve for typing in test.
    // (They must not conflict; using identical names so the compiler accepts building calldata structs.)
    // Note: Solidity allows using the types declared in imported C; however some complex types are nested
    // and already available via the import. We simply reference them via C where needed below.

    function setUp() public {
        c = new C();
    }

    // Fuzz the maintenance parameter: when we initialize the product with a maintenance != ONE,
    // the reference contract will return that stored value, but the mutant returns ONE always.
    // We therefore assert that c.maintenance(address(this)) equals the maintenance we initialized.
    // This property holds for the reference for all inputs; the mutant will fail when the fuzzed
    // maintenance != UFixed18Lib.ONE.
    function testFuzz_property(uint256 maintenanceRaw) public {
        // Bound maintenanceRaw to a wide uint256 range but allow zero as valid.
        // We construct a UFixed18 via the library wrapper function present in the imported C.
        // To avoid depending on internal constructors, we use C's initialize signature which expects
        // a ProductInfo calldata struct. We'll build that with reasonable defaults and set maintenance.

        // Create a JumpRateUtilizationCurve struct with zeros using bytes packing via abi.encode/decode.
        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        // Build ProductInfo as expected by C.initialize
        IOracleProvider oracle = IOracleProvider(address(this)); // dummy; C will call Address.isContract so use c's controller path later
        PayoffDefinition memory payoffDef;

        // Convert maintenanceRaw into UFixed18 by using the UFixed18 type's wrap constructor
        // The test imports C which defines UFixed18 as a type; we can wrap directly.
        UFixed18 maintenance = UFixed18.wrap(maintenanceRaw);

        // For other UFixed18 params use ZERO via UFixed18.wrap(0)
        UFixed18 zero = UFixed18.wrap(0);

        // Prepare product info struct in the shape expected by C
        C.ProductInfo memory pinfo = C.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: payoffDef,
            oracle: IOracleProvider(address(1)), // use a non-zero address to satisfy Address.isContract check in initialize (but it will fail if non-contract).
            maintenance: maintenance,
            fundingFee: zero,
            makerFee: zero,
            takerFee: zero,
            positionFee: zero,
            makerLimit: zero,
            utilizationCurve: curve
        });

        // The initialize call requires that msg.sender is the controller (IController). In the real C.initialize
        // it expects msg.sender to be controller address (it does __UControllerProvider__initialize(IController(msg.sender))).
        // To satisfy this, we deploy a minimal controller stub that is a contract and will accept being treated as IController.
        ControllerStub controller = new ControllerStub(address(this));

        // We must call initialize with msg.sender == controller. Use vm.prank to impersonate controller.
        vm.prank(address(controller));
        c.initialize(pinfo);

        // Now read back maintenance for some account (use address(this)).
        UFixed18 mRead = c.maintenance(address(this));

        // The property: the maintenance getter returns the exact value we initialized.
        // This is true for reference C for all maintenanceRaw inputs; the mutant that returns ONE
        // will fail when maintenance != ONE. Assert equality.
        // Single assertion requirement: use assertTrue with equality comparison.
        assertTrue(UFixed18.unwrap(mRead) == UFixed18.unwrap(maintenance));
    }
}

// Minimal controller stub to satisfy __UControllerProvider__initialize check in initialize.
contract ControllerStub {
    address public ownerAddress;
    constructor(address owner_) { ownerAddress = owner_; }
    function isProduct(C product) external view returns (bool) { return false; }
    function owner() external view returns (address) { return ownerAddress; }
    function owner(uint256) external view returns (address) { return ownerAddress; }
    function coordinatorFor(C) external view returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return ownerAddress; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the maintenance parameter used during initialize and an arbitrary account address
    function testFuzz_property(uint256 maintenanceRaw, address account) public {
        // keep maintenance within a wide admissible UFixed18 range (scaled by 1e18 internally)
        maintenanceRaw = bound(maintenanceRaw, 0, type(uint128).max);

        // construct a UFixed18 value by using the library's ONE multiplier (we can't reference library internals here),
        // but product initialization expects UFixed18 typed; we craft it via address cast trick: C.ProductInfo uses UFixed18 fields
        // Since we cannot construct UFixed18 directly here (it's a user-defined type in the imported contract), we instead
        // prepare a ProductInfo via low-level ABI encoding and call initialize through a helper contract that knows the struct layout.

        // Deploy helper that can call initialize with arbitrary maintenance value.
        InitializerHelper helper = new InitializerHelper(c);

        // Prepare other required fields with dummy but admissible values.
        // For maintenance we pass the fuzzed value as the raw uint256 representation of UFixed18 (i.e., scaled by 1e18 not required here,
        // the contract treats UFixed18 as uint256 raw values). We'll choose maintenanceRaw as-is.

        // Build product info via helper and call initialize
        helper.initializeProduct(maintenanceRaw, account);

        // Now call maintenance(account) and assert it equals the originally stored maintenanceRaw value.
        // We observe the return value as raw UFixed18 (uint256 under the hood). Use try/catch to be robust if call reverts.
        bool ok;
        try c.maintenance(account) returns (uint256 returnedRaw) {
            // The reference implementation stores the maintenance value and returns it for any account.
            // The mutant always returns UFixed18Lib.ONE (raw value 1e18), so when maintenanceRaw != 1e18 the mutant will differ.
            ok = (returnedRaw == maintenanceRaw);
        } catch {
            ok = false;
        }

        // This single assertion is satisfied for the reference C for all inputs (it returns stored maintenanceRaw),
        // and fails on the mutant when maintenanceRaw != UFixed18Lib.ONE (1e18), which the fuzzer can find.
        assertTrue(ok);
    }
}

// Helper that knows the ProductInfo layout and calls initialize on the product contract.
contract InitializerHelper {
    C target;
    constructor(C _target) { target = _target; }

    // The ProductInfo struct in C (IProduct.ProductInfo) ABI layout (in order):
    // string name;
    // string symbol;
    // PayoffDefinition payoffDefinition; (we can pass an empty 32-byte placeholder since payoffDefinition.valid() is called in __UPayoffProvider__initialize;
    //    to avoid complexity we pass a minimal valid payoffDefinition by crafting bytes that make valid() true in original contract —
    //    however we cannot call internal library here; instead we rely on the contract not performing heavy checks beyond existence in this test environment.
    // IOracleProvider oracle; (address)
    // UFixed18 maintenance;
    // UFixed18 fundingFee;
    // UFixed18 makerFee;
    // UFixed18 takerFee;
    // UFixed18 positionFee;
    // UFixed18 makerLimit;
    // JumpRateUtilizationCurve utilizationCurve; (packed struct)
    // To keep things simple and avoid complex struct construction in Solidity, we will encode a ProductInfo where
    // strings are empty, payable address(1) as oracle, and zeros for numeric fields. The key maintenance field we set to maintenanceRaw.

    function initializeProduct(uint256 maintenanceRaw, address callerAccount) public {
        // Build ABI-encoded ProductInfo matching the external initialize(ProductInfo calldata) parameter.
        // We'll provide minimal plausible values: empty strings, zeroed payoffDefinition (32 bytes), oracle address = address(this),
        // maintenance = maintenanceRaw, other numeric params zero, and an empty utilization curve (zeros).

