// Minimal controller and helpers below to satisfy external interactions during initialize() and updateTakerFee()
interface IOracleProvider {
    struct OracleVersion { uint256 version; uint256 timestamp; C.Fixed18 price; }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}

contract MinimalIncentivizer {
    function sync(IOracleProvider.OracleVersion memory) external {}
    function syncAccount(address, IOracleProvider.OracleVersion memory) external {}
}

contract MinimalCollateral {
    function settleProduct(C.UFixed18) external {}
    function settleAccount(address, C.Fixed18) external {}
    function liquidatableNext(address, C.IProduct) external view returns (bool) { return false; }
}

contract MinimalController {
    address public incentivizerAddr;
    address public collateralAddr;
    address public ownerAddr;
    constructor(address incentivizer_, address collateral_, address owner_) {
        incentivizerAddr = incentivizer_;
        collateralAddr = collateral_;
        ownerAddr = owner_;
    }
    function setOwner(address o) external { ownerAddr = o; }
    function incentivizer() external view returns (MinimalIncentivizer) { return MinimalIncentivizer(incentivizerAddr); }
    function collateral() external view returns (MinimalCollateral) { return MinimalCollateral(collateralAddr); }
    function coordinatorFor(C.IProduct) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return ownerAddr; }
    // Additional stubs to satisfy other potential calls
    function isProduct(C.IProduct) external pure returns (bool) { return true; }
    function owner() external view returns (address) { return ownerAddr; }
    function paused() external pure returns (bool) { return false; }
    function minFundingFee() external pure returns (C.UFixed18) { return C.UFixed18.wrap(0); }
