            // The full struct layout is (bool makerFeeUpdated, uint64 pendingMakerFee, bool takerFeeUpdated, uint64 pendingTakerFee, bool positionFeeUpdated, uint64 pendingPositionFee)
            // Solidity ABI will encode booleans as uint8 padded to 32 bytes and uint64 as uint64 padded to 32 bytes.
